import{_ as e,o as t,c as i,a3 as l}from"./chunks/framework.B5WAEDB7.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/availability-patterns.md","filePath":"core-concepts/availability-patterns.md"}'),r={name:"core-concepts/availability-patterns.md"};function s(n,a,o,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h2 id="availability-patterns" tabindex="-1">Availability patterns <a class="header-anchor" href="#availability-patterns" aria-label="Permalink to &quot;Availability patterns&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Availability patterns.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p>There are two complementary patterns to support high availability: <strong>fail-over</strong> and <strong>replication</strong>.</p><h3 id="fail-over" tabindex="-1">Fail-over <a class="header-anchor" href="#fail-over" aria-label="Permalink to &quot;Fail-over&quot;">​</a></h3><h4 id="active-passive" tabindex="-1">Active-passive <a class="header-anchor" href="#active-passive" aria-label="Permalink to &quot;Active-passive&quot;">​</a></h4><p>With active-passive fail-over, heartbeats are sent between the active and the passive server on standby. If the heartbeat is interrupted, the passive server takes over the active&#39;s IP address and resumes service.</p><p>The length of downtime is determined by whether the passive server is already running in &#39;hot&#39; standby or whether it needs to start up from &#39;cold&#39; standby. Only the active server handles traffic.</p><p>Active-passive failover can also be referred to as master-slave failover.</p><h4 id="active-active" tabindex="-1">Active-active <a class="header-anchor" href="#active-active" aria-label="Permalink to &quot;Active-active&quot;">​</a></h4><p>In active-active, both servers are managing traffic, spreading the load between them.</p><p>If the servers are public-facing, the DNS would need to know about the public IPs of both servers. If the servers are internal-facing, application logic would need to know about both servers.</p><p>Active-active failover can also be referred to as master-master failover.</p><h3 id="disadvantage-s-failover" tabindex="-1">Disadvantage(s): failover <a class="header-anchor" href="#disadvantage-s-failover" aria-label="Permalink to &quot;Disadvantage(s): failover&quot;">​</a></h3><ul><li>Fail-over adds more hardware and additional complexity.</li><li>There is a potential for loss of data if the active system fails before any newly written data can be replicated to the passive.</li></ul><h3 id="replication" tabindex="-1">Replication <a class="header-anchor" href="#replication" aria-label="Permalink to &quot;Replication&quot;">​</a></h3><h4 id="master-slave-and-master-master" tabindex="-1">Master-slave and master-master <a class="header-anchor" href="#master-slave-and-master-master" aria-label="Permalink to &quot;Master-slave and master-master&quot;">​</a></h4><p>This topic is further discussed in the <a href="/core-concepts/database.html">Database</a> section:</p><ul><li><a href="#master-slave-replication">Master-slave replication</a></li><li><a href="#master-master-replication">Master-master replication</a></li></ul><h3 id="availability-in-numbers" tabindex="-1">Availability in numbers <a class="header-anchor" href="#availability-in-numbers" aria-label="Permalink to &quot;Availability in numbers&quot;">​</a></h3><p>Availability is often quantified by uptime (or downtime) as a percentage of time the service is available. Availability is generally measured in number of 9s--a service with 99.99% availability is described as having four 9s.</p><h4 id="_99-9-availability-three-9s" tabindex="-1">99.9% availability - three 9s <a class="header-anchor" href="#_99-9-availability-three-9s" aria-label="Permalink to &quot;99.9% availability - three 9s&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Duration</th><th>Acceptable downtime</th></tr></thead><tbody><tr><td>Downtime per year</td><td>8h 45min 57s</td></tr><tr><td>Downtime per month</td><td>43m 49.7s</td></tr><tr><td>Downtime per week</td><td>10m 4.8s</td></tr><tr><td>Downtime per day</td><td>1m 26.4s</td></tr></tbody></table><h4 id="_99-99-availability-four-9s" tabindex="-1">99.99% availability - four 9s <a class="header-anchor" href="#_99-99-availability-four-9s" aria-label="Permalink to &quot;99.99% availability - four 9s&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Duration</th><th>Acceptable downtime</th></tr></thead><tbody><tr><td>Downtime per year</td><td>52min 35.7s</td></tr><tr><td>Downtime per month</td><td>4m 23s</td></tr><tr><td>Downtime per week</td><td>1m 5s</td></tr><tr><td>Downtime per day</td><td>8.6s</td></tr></tbody></table><h4 id="availability-in-parallel-vs-in-sequence" tabindex="-1">Availability in parallel vs in sequence <a class="header-anchor" href="#availability-in-parallel-vs-in-sequence" aria-label="Permalink to &quot;Availability in parallel vs in sequence&quot;">​</a></h4><p>If a service consists of multiple components prone to failure, the service&#39;s overall availability depends on whether the components are in sequence or in parallel.</p><h6 id="in-sequence" tabindex="-1">In sequence <a class="header-anchor" href="#in-sequence" aria-label="Permalink to &quot;In sequence&quot;">​</a></h6><p>Overall availability decreases when two components with availability &lt; 100% are in sequence:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Availability (Total) = Availability (Foo) * Availability (Bar)</span></span></code></pre></div><p>If both <code>Foo</code> and <code>Bar</code> each had 99.9% availability, their total availability in sequence would be 99.8%.</p><h6 id="in-parallel" tabindex="-1">In parallel <a class="header-anchor" href="#in-parallel" aria-label="Permalink to &quot;In parallel&quot;">​</a></h6><p>Overall availability increases when two components with availability &lt; 100% are in parallel:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Availability (Total) = 1 - (1 - Availability (Foo)) * (1 - Availability (Bar))</span></span></code></pre></div><p>If both <code>Foo</code> and <code>Bar</code> each had 99.9% availability, their total availability in parallel would be 99.9999%.</p>',34)])])}const b=e(r,[["render",s]]);export{v as __pageData,b as default};
